/**
 * Allows planners to adjust doctrinal burn rates per weapon system without touching the database. Changes are immediately reflected in unit-level DOS calculations. The full rate matrix (weapon × DODIC × GCE/Non-GCE) is seeded once by `scripts/src/seed.ts`; only edits are exposed via the API. There is intentionally no list/create/delete endpoint for rate rows.
 * @summary Edit doctrinal combat-load / assault / sustain rates for a weapon-DODIC pair
 */
export const getUpdateWeaponDodicRateUrl = (
  weaponSystemId: string,
  rateId: string,
) => {
  return `/api/weapon-systems/${weaponSystemId}/dodic-rates/${rateId}`;
};

export const updateWeaponDodicRate = async (
  weaponSystemId: string,
  rateId: string,
  weaponDodicRateInput: WeaponDodicRateInput,
  options?: RequestInit,
): Promise<WeaponDodicRate> => {
  return customFetch<WeaponDodicRate>(
    getUpdateWeaponDodicRateUrl(weaponSystemId, rateId),
    {
      ...options,
      method: "PATCH",
      headers: { "Content-Type": "application/json", ...options?.headers },
      body: JSON.stringify(weaponDodicRateInput),
    },
  );
};

