/**
 * @summary List MARLOG-opened pull requests against the SPIRE repo
 */
export const getListSpirePrsUrl = (params?: ListSpirePrsParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/spire-pr?${stringifiedParams}`
    : `/api/spire-pr`;
};

export const listSpirePrs = async (
  params?: ListSpirePrsParams,
  options?: RequestInit,
): Promise<SpirePr[]> => {
  return customFetch<SpirePr[]>(getListSpirePrsUrl(params), {
    ...options,
    method: "GET",
  });
};

export const getListSpirePrsQueryKey = (params?: ListSpirePrsParams) => {
  return [`/api/spire-pr`, ...(params ? [params] : [])] as const;
};

